## Full CSS Framework

```css
/* === Reset === */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

/* === Design Tokens === */
:root {
  /* Dark mode (cover) */
  --bg-deep: #141414;
  --bg-surface: #1E1E1E;
  --bg-elevated: #282828;
  --border-subtle: rgba(255, 255, 255, 0.08);
  --text-bright: #f0f3f6;
  --text-secondary-dark: #9ca3af;
  --text-muted-dark: #6e7681;

  /* Light mode (content — default) */
  --bg-light: #FAF7F2;
  --bg-light-surface: #F2EDE6;
  --border-light: rgba(15, 14, 14, 0.1);
  --text-primary: #0f0e0e;
  --text-secondary: #57606a;
  --text-muted: #8b949e;

  /* Accent */
  --accent: #3D7A5C;
  --accent-light: #6AB88A;

  /* Semantic */
  --green: #2e8b57;
  --red: #c0392b;
  --amber: #D97706;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.04);
  --shadow-md: 0 2px 8px rgba(0,0,0,0.06);
}

/* === Typography === */
body {
  font-family: 'Switzer', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-light);
}

.mono {
  font-family: 'Cartograph CF', 'JetBrains Mono', 'Consolas', monospace;
}

h1 {
  font-weight: 300;
  font-size: 48px;
  letter-spacing: -0.04em;
  line-height: 1.1;
}

h2 {
  font-weight: 400;
  font-size: 28px;
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin-bottom: 16px;
}

h3 {
  font-weight: 500;
  font-size: 20px;
  line-height: 1.3;
  margin-bottom: 12px;
}

p { margin-bottom: 12px; }

.label {
  font-family: 'Cartograph CF', 'JetBrains Mono', monospace;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
}

/* === Page Layout === */
.page {
  max-width: 900px;
  margin: 0 auto;
  padding: 60px 80px;
  background: var(--bg-light);
  min-height: 100vh;
}

.page--dark {
  background: var(--bg-deep);
  color: var(--text-bright);
}

.page + .page {
  border-top: 1px solid var(--border-light);
}

/* === Cover Page === */
.cover {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding-bottom: 80px;
}

.cover h1 {
  font-size: 64px;
  margin-bottom: 16px;
}

.cover .subtitle {
  font-size: 20px;
  color: var(--text-secondary-dark);
  margin-bottom: 40px;
  max-width: 600px;
}

.cover-meta {
  font-family: 'Cartograph CF', monospace;
  font-size: 13px;
  color: var(--text-muted-dark);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cover-meta span + span::before {
  content: " · ";
  color: var(--text-muted-dark);
}

/* === Section Spacing === */
.section {
  margin-bottom: 48px;
}

.section-label {
  font-family: 'Cartograph CF', monospace;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  margin-bottom: 8px;
}

/* === KPI Cards === */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.kpi-card {
  background: var(--bg-light-surface);
  border: 1px solid var(--border-light);
  border-radius: 12px;
  padding: 24px;
}

.kpi-card .label {
  margin-bottom: 8px;
}

.kpi-value {
  font-family: 'Cartograph CF', monospace;
  font-size: 36px;
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 4px;
}

.kpi-detail {
