  color: var(--text-secondary);
}

.kpi-value--good { color: var(--green); }
.kpi-value--warning { color: var(--amber); }
.kpi-value--critical { color: var(--red); }

/* === Data Tables === */
.data-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 24px;
}

.data-table th {
  font-family: 'Cartograph CF', monospace;
  font-size: 13px;
