  letter-spacing: 0.08em;
  color: var(--text-muted);
  text-align: left;
  padding: 12px 16px;
  border-bottom: 2px solid var(--border-light);
  font-weight: 400;
}

.data-table td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--border-light);
  font-size: 15px;
}

.data-table td.mono,
.data-table td:nth-child(n+2) {
  font-family: 'Cartograph CF', monospace;
  font-size: 14px;
}

.data-table tr:last-child td {
  border-bottom: none;
}

.data-table .status-good { color: var(--green); font-weight: 600; }
.data-table .status-warning { color: var(--amber); font-weight: 600; }
.data-table .status-critical { color: var(--red); font-weight: 600; }

/* === Callout Boxes === */
.callout {
  background: var(--bg-light-surface);
  border: 1px solid var(--border-light);
  border-radius: 10px;
  padding: 20px 24px;
  margin-bottom: 24px;
}

.callout--accent {
  background: #eaf2ed;
  border-color: rgba(61, 122, 92, 0.2);
}

.callout--warning {
  background: #fef3cd;
  border-color: rgba(217, 119, 6, 0.2);
}

.callout--critical {
  background: #fde8e8;
  border-color: rgba(192, 57, 43, 0.2);
}

.callout strong {
  display: inline;
}

.callout p {
  margin-bottom: 0;
  font-size: 15px;
  line-height: 1.5;
}

/* === Priority Banners === */
.banner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 20px;
  border-radius: 10px;
  font-size: 15px;
  font-weight: 500;
  margin-bottom: 24px;
}

.banner--critical {
  background: #fde8e8;
  color: var(--red);
  border: 1px solid rgba(192, 57, 43, 0.2);
}

.banner--warning {
  background: #fef3cd;
  color: #92400e;
  border: 1px solid rgba(217, 119, 6, 0.2);
}

.banner--info {
  background: #eaf2ed;
  color: #1a5632;
  border: 1px solid rgba(61, 122, 92, 0.2);
}

.banner-icon {
  font-size: 18px;
  flex-shrink: 0;
}

/* === Recommendation Cards === */
.rec-grid {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.rec-card {
  background: var(--bg-light-surface);
  border: 1px solid var(--border-light);
  border-radius: 10px;
  padding: 20px 24px;
  display: flex;
  gap: 16px;
}

.rec-number {
  font-family: 'Cartograph CF', monospace;
  font-size: 24px;
  font-weight: 700;
  color: var(--accent);
  min-width: 32px;
}

.rec-content { flex: 1; }

.rec-title {
  font-weight: 500;
  font-size: 16px;
  margin-bottom: 4px;
}

.rec-desc {
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 8px;
}

.rec-badges {
  display: flex;
  gap: 8px;
}

.badge {
  font-family: 'Cartograph CF', monospace;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 3px 8px;
  border-radius: 4px;
  background: var(--bg-light);
  border: 1px solid var(--border-light);
  color: var(--text-muted);
}

.badge--high-impact {
  background: #eaf2ed;
  border-color: rgba(61, 122, 92, 0.2);
  color: var(--accent);
}

.badge--low-effort {
  background: #e8f0fe;
  border-color: rgba(58, 134, 255, 0.2);
  color: #2563eb;
}

/* === Section Dividers === */
.divider {
  border: none;
  height: 1px;
  background: var(--border-light);
  margin: 48px 0;
}

/* === Lists === */
.bullet-list {
  list-style: none;
  padding-left: 0;
  margin-bottom: 20px;
}

.bullet-list li {
  padding: 6px 0 6px 20px;
  position: relative;
  font-size: 15px;
}

.bullet-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 14px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
}

.numbered-list {
  list-style: none;
  padding-left: 0;
  counter-reset: item;
  margin-bottom: 20px;
}

.numbered-list li {
  padding: 6px 0 6px 32px;
  position: relative;
  font-size: 15px;
  counter-increment: item;
}

.numbered-list li::before {
  content: counter(item);
  position: absolute;
  left: 0;
  top: 6px;
  font-family: 'Cartograph CF', monospace;
  font-weight: 700;
  font-size: 14px;
  color: var(--accent);
  width: 24px;
  text-align: center;
}

/* === Table of Contents === */
.toc {
  margin-bottom: 48px;
}

.toc-item {
  display: flex;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 1px solid var(--border-light);
  font-size: 15px;
}

.toc-item .toc-page {
  font-family: 'Cartograph CF', monospace;
  font-size: 14px;
  color: var(--text-muted);
}

/* === Print Styles === */
@media print {
  * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
  body { background: white; margin: 0; }
  .page {
    break-after: page;
    break-inside: avoid;
    min-height: auto;
    box-shadow: none;
    border: none;
  }
  .page:last-child { break-after: avoid; }
  .kpi-card, .rec-card, .callout { box-shadow: none !important; }
}
```

## HTML Composition Patterns

### Cover Page

```html
<div class="page page--dark cover">
  <div class="cover-meta">
    <span>Prepared for Client Name</span>
    <span>March 2026</span>
  </div>
  <h1>Report Title</h1>
  <p class="subtitle">A comprehensive analysis of performance, opportunities, and strategic recommendations.</p>
</div>
```

### Executive Summary

```html
<div class="page">
  <div class="section">
    <div class="section-label">Executive Summary</div>
    <h2>Key Findings at a Glance</h2>

    <div class="kpi-grid">
      <div class="kpi-card">
        <div class="label">Revenue</div>
        <div class="kpi-value kpi-value--good">$2.4M</div>
        <div class="kpi-detail">+18% vs target</div>
      </div>
      <div class="kpi-card">
        <div class="label">Conversion Rate</div>
        <div class="kpi-value kpi-value--warning">2.1%</div>
        <div class="kpi-detail">Below 2.5% benchmark</div>
      </div>
      <!-- more cards -->
    </div>

    <div class="callout">
      <p><strong>Bottom line:</strong> Revenue exceeded targets but conversion efficiency is declining. Recommend prioritizing funnel optimization over acquisition spend increase.</p>
    </div>
  </div>
</div>
```

